mapper.select:
SELECT ml.name AS type, COUNT(DISTINCT mu.id) AS count FROM member_sign ms INNER JOIN member_user mu ON ms.user_id = mu.id AND mu.deleted = 0 INNER JOIN member_level ml ON mu.level_id = ml.id AND ml.deleted = 0 WHERE ms.deleted = 0
AND ms.sign_date >= #{start}
AND ms.sign_date <= #{end}
GROUP BY ml.id, ml.name, ml.level_value ORDER BY ml.level_value ASC
